use roottrace::{verify_membership, VerifyError};

fn main() {
    // 目标记录的全部字节：批次中第 2 条记录 "alpha"（不含分隔它的 LF）。
    let record: &[u8] = b"alpha";
    // `roottrace prove batch.txt 2` 的原样输出。
    let proof: &[u8] = br#"{"tree_size":5,"leaf_index":2,"root":"90dabc2745c8500b60e44505fceebe7ab2a3b2fcebcb9d208b0e267cb7f700d3","audit_path":["4c79d0d62f7cf5ca8874155f2d3b875f2625da2bb3abc86bbd6833f25ba90e51","983cb57c04cddd52634edab38a7bef85708a974f114bbd9aa9ec5d4ce6656b4b","5c7117fb9edb0cec387257891105da6a6616722af247083e2d6eda671529cdc5"]}"#;
    // 独立确认的可信值。
    let trusted_tree_size: u64 = 5;
    let trusted_root: [u8; 32] = [
        0x90, 0xda, 0xbc, 0x27, 0x45, 0xc8, 0x50, 0x0b,
        0x60, 0xe4, 0x45, 0x05, 0xfc, 0xee, 0xbe, 0x7a,
        0xb2, 0xa3, 0xb2, 0xfc, 0xeb, 0xcb, 0x9d, 0x20,
        0x8b, 0x0e, 0x26, 0x7c, 0xb7, 0xf7, 0x00, 0xd3,
    ];

    match verify_membership(record, proof, trusted_tree_size, &trusted_root) {
        Ok(membership) => {
            println!("leaf_index = {}", membership.leaf_index());
            println!("tree_size  = {}", membership.tree_size());
            println!("root       = {}", hex(membership.root()));
        }
        Err(VerifyError::MalformedProof(reason)) => eprintln!("证明格式无效: {reason}"),
        Err(VerifyError::VerificationFailed(reason)) => eprintln!("核验失败: {reason}"),
        Err(VerifyError::InvalidTrustedSize) => eprintln!("可信树大小必须为正整数"),
    }

    // 追加 LF 后应核验失败
    let record_lf: &[u8] = b"alpha\n";
    match verify_membership(record_lf, proof, trusted_tree_size, &trusted_root) {
        Ok(_) => println!("unexpected ok"),
        Err(e) => println!("with LF -> {}", variant(&e)),
    }
    // 可信树大小为零
    match verify_membership(record, proof, 0, &trusted_root) {
        Ok(_) => println!("unexpected ok"),
        Err(e) => println!("size 0 -> {}", variant(&e)),
    }
    // 格式无效的证明
    let bad_proof: &[u8] = br#"{"tree_size":5,"leaf_index":2}"#;
    match verify_membership(record, bad_proof, trusted_tree_size, &trusted_root) {
        Ok(_) => println!("unexpected ok"),
        Err(e) => println!("bad proof -> {}", variant(&e)),
    }
}

fn hex(d: &[u8; 32]) -> String {
    d.iter().map(|b| format!("{b:02x}")).collect()
}

fn variant(e: &VerifyError) -> &'static str {
    match e {
        VerifyError::MalformedProof(_) => "MalformedProof",
        VerifyError::VerificationFailed(_) => "VerificationFailed",
        VerifyError::InvalidTrustedSize => "InvalidTrustedSize",
    }
}
EOF
