        0x60, 0xe4, 0x45, 0x05, 0xfc, 0xee, 0xbe, 0x7a,
        0xb2, 0xa3, 0xb2, 0xfc, 0xeb, 0xcb, 0x9d, 0x20,
        0x8b, 0x0e, 0x26, 0x7c, 0xb7, 0xf7, 0x00, 0xd3,
    ];

    match verify_membership(record, proof, trusted_tree_size, &trusted_root) {
        Ok(membership) => {
            println!("记录序号 {}", membership.leaf_index());
            println!("树大小   {}", membership.tree_size());
            println!("根值     {:?}", membership.root());
        }
        Err(VerifyError::MalformedProof(reason)) => eprintln!("证明格式无效: {reason}"),
        Err(VerifyError::VerificationFailed(reason)) => eprintln!("核验失败: {reason}"),
        Err(VerifyError::InvalidTrustedSize) => eprintln!("可信树大小必须为正整数"),
    }

    // === README 追加 LF 片段（逐字） ===
    let record: &[u8] = b"alpha\n";
    assert!(matches!(
        verify_membership(record, proof, trusted_tree_size, &trusted_root),
        Err(VerifyError::VerificationFailed(_))
    ));

    // === README 文字断言：trusted_tree_size 改成 6 → VerificationFailed ===
    assert!(matches!(
        verify_membership(b"alpha", proof, 6, &trusted_root),
        Err(VerifyError::VerificationFailed(_))
    ));
    // === 缺字段证明 → MalformedProof ===
    assert!(matches!(
        verify_membership(b"alpha", br#"{"tree_size":5,"leaf_index":2}"#, 5, &trusted_root),
        Err(VerifyError::MalformedProof(_))
    ));
    // === 可信树大小 0 → InvalidTrustedSize ===
    assert!(matches!(
        verify_membership(b"alpha", proof, 0, &trusted_root),
        Err(VerifyError::InvalidTrustedSize)
    ));
    println!("all assertions passed");
}
